//! T-19 sb-act acceptance round 4, items 19-23: D-408 (non-submit Pay and Account buttons
//! in form context, Enter anywhere in a chord, leave group and wipe device are Delete), and
//! the raise-only check of hard rule 4 against the classes `crates/sb-act/src` gave at
//! 3122050, before D-408. Public API only; fixtures are I-5 wire JSON in `common/mod.rs`.
//!
//! The baseline `bench/fixtures/t19_pre_d408_classes.txt` is regenerated by running
//! `raise_only_every_fixture_vs_pre_d408` with `T19_WRITE_BASELINE=<path>` in a tree whose
//! `crates/sb-act/src` is at 3122050 (see the round-4 section of
//! `bench/results/accept-T-19-sb-act.md`).

use std::collections::BTreeMap;

use harness_core::Class;
use sb_act::{classify_step, parse, quote, Step};
use sb_sheet::{ElemRef, IndexRow};

mod common;
use common::{raise_programs, ALL, D408, IMPLICIT, KEYS, LOGIN, REGISTER};

const BASELINE: &str = include_str!("../../../bench/fixtures/t19_pre_d408_classes.txt");

fn rows(json: &str) -> Vec<IndexRow> {
    serde_json::from_str(json).expect("I-5 wire JSON")
}

fn class_of(program: &str, index: &[IndexRow]) -> Class {
    let steps = parse(program).unwrap_or_else(|e| panic!("{program:?}: {e}"));
    assert_eq!(steps.len(), 1, "{program:?}");
    classify_step(&steps[0], index).class
}

fn ref_of(r: &IndexRow) -> String {
    if r.frame == 0 {
        format!("#{}", r.id)
    } else {
        format!("#f{}.{}", r.frame, r.id)
    }
}

/// Class of `k<ref>=<key>` through the parser (key quoted by `q()`, D-52) and as a
/// hand-built `Step::Key`; both must agree.
fn key_class(row: &IndexRow, key: &str, index: &[IndexRow]) -> Class {
    let program = format!("k{}={}", ref_of(row), quote(key));
    let built = Step::Key {
        target: ElemRef {
            frame: row.frame,
            id: row.id,
        },
        key: key.to_string(),
    };
    let steps = parse(&program).unwrap_or_else(|e| panic!("{program:?}: {e}"));
    assert_eq!(steps, vec![built.clone()], "{program:?}");
    let parsed = classify_step(&steps[0], index).class;
    assert_eq!(parsed, classify_step(&built, index).class, "{program:?}");
    parsed
}

fn row(index: &[IndexRow], frame: u32, id: u32) -> &IndexRow {
    index
        .iter()
        .find(|r| r.id == id && r.frame == frame)
        .unwrap_or_else(|| panic!("no row #f{frame}.{id}"))
}

/// Key values that name Enter under D-408 (2).
const ENTER_CHORDS: &[&str] = &[
    "Enter",
    "enter",
    "ENTER",
    "Return",
    "NumpadEnter",
    "Enter+",
    "Enter+Shift",
    "Shift+Enter",
    "Control+Shift+Enter",
    "Alt+Enter",
    "Enter+a",
    " Enter",
    "Enter ",
    "Enter\t",
    "\tEnter",
    "Enter\0",
    "NumpadEnter+Control",
    "Meta+Return",
];

/// Key values that only contain the letters of Enter or Return.
const NOT_ENTER: &[&str] = &[
    "Enterprise",
    "Entertain",
    "Reenter",
    "Returns",
    "Shift+Enterprise",
];

// ---- item 19: D-408 (1) non-submit buttons in form context, positives ----

#[test]
fn d408_non_submit_pay_buttons_in_form_context_are_pay() {
    let idx = rows(D408);
    for r in [302, 303, 304, 311, 321, 322, 323, 324, 325, 326, 351] {
        let x = row(&idx, 0, r);
        assert!(
            !x.flags.submit && !x.state.submitish,
            "#{r} must be non-submit"
        );
        assert_eq!(
            class_of(&format!("c#{r}"), &idx),
            Class::Pay,
            "c#{r} {}",
            x.name
        );
        assert_eq!(
            key_class(x, "Space", &idx),
            Class::Pay,
            "k#{r}=Space {}",
            x.name
        );
        assert_eq!(
            key_class(x, "Enter", &idx),
            Class::Pay,
            "k#{r}=Enter {}",
            x.name
        );
    }
    // The menuitem "Place bid" and the formless "Complete" under the card form's heading.
    assert_eq!(row(&idx, 0, 304).role, "menuitem");
    assert!(row(&idx, 0, 351).form.is_none());
}

#[test]
fn d408_non_submit_account_buttons_in_form_context_are_account() {
    let idx = rows(D408);
    for (r, what) in [
        (331, "Create account in a signup form"),
        (337, "Create account in a login form"),
        (341, "Change password in a profile form"),
        (356, "Add, formless, sharing the Passkeys heading of a form"),
    ] {
        assert_eq!(class_of(&format!("c#{r}"), &idx), Class::Account, "{what}");
        assert_eq!(
            key_class(row(&idx, 0, r), "Space", &idx),
            Class::Account,
            "{what} Space"
        );
    }
    // The login's own submit is still Submit.
    assert_eq!(class_of("c#338", &idx), Class::Submit);
}

// ---- item 20: D-408 (1) negatives ----

#[test]
fn d408_negatives_stay_navigate() {
    let idx = rows(D408);
    for (r, what) in [
        (305, "Show details in a card form"),
        (306, "Back to top in a card form"),
        (307, "Complete purchase link in a card form"),
        (312, "Edit address in a Checkout form"),
        (327, "Confirm in a form without Pay evidence"),
        (332, "Show password in a signup form"),
        (352, "Show details sharing the card form's heading"),
        (353, "Complete link sharing the card form's heading"),
        (360, "formless Create account, no heading"),
        (361, "formless Create account, heading no form shares"),
    ] {
        assert_eq!(class_of(&format!("c#{r}"), &idx), Class::Navigate, "{what}");
        assert_eq!(
            key_class(row(&idx, 0, r), "Space", &idx),
            Class::Navigate,
            "{what} Space"
        );
    }
    // A button with the card form's heading text but in another frame shares no form.
    // Round 5 (D-409 (2)): a formless button named with a pay_words phrase is Pay in any
    // frame, so the same row renamed "Complete purchase" is Pay. "Complete" alone is a
    // single PAY_TOKENS word, not a pay_words phrase, so #f1.362 itself stays Navigate.
    assert_eq!(class_of("c#f1.362", &idx), Class::Navigate);
    let mut renamed = idx.clone();
    renamed
        .iter_mut()
        .find(|r| r.frame == 1 && r.id == 362)
        .expect("#f1.362")
        .name = "Complete purchase".to_string();
    assert_eq!(class_of("c#f1.362", &renamed), Class::Pay);
    assert_eq!(
        key_class(row(&renamed, 1, 362), "Space", &renamed),
        Class::Pay
    );
    // A checkbox is not a button: toggling "Subscribe to offers" in a card form is Fill.
    assert_eq!(class_of("c#308", &idx), Class::Fill);
    // Enter in the card form is still the form max (D-406 (2)), even on Show details.
    for r in [305, 306, 308] {
        assert_eq!(
            key_class(row(&idx, 0, r), "Enter", &idx),
            Class::Pay,
            "k#{r}=Enter"
        );
    }
}

// ---- item 21: D-408 (2) Enter in any chord segment ----

#[test]
fn d408_enter_chords_are_enter() {
    let d = rows(D408);
    let imp = rows(IMPLICIT);
    let keys = rows(KEYS);
    let login = rows(LOGIN);
    let reg = rows(REGISTER);
    let cases: [(&[IndexRow], u32, Class, &str); 6] = [
        (&d, 301, Class::Pay, "Promo field in a card form"),
        (&imp, 120, Class::Submit, "formless chat composer"),
        (&keys, 100, Class::Delete, "mail toolbar Delete button"),
        (&keys, 103, Class::Navigate, "nav link"),
        (&login, 21, Class::Submit, "login password"),
        (&reg, 4, Class::Account, "register email"),
    ];
    for (idx, id, want, what) in cases {
        let r = row(idx, 0, id);
        for k in ENTER_CHORDS {
            assert_eq!(key_class(r, k, idx), want, "{what} k#{id}={k:?}");
        }
    }
    // The B-7 program form of the handoff example.
    assert_eq!(class_of("k#301=Enter+Shift", &d), Class::Pay);
}

#[test]
fn d408_enterprise_is_not_enter() {
    let d = rows(D408);
    let imp = rows(IMPLICIT);
    let reg = rows(REGISTER);
    for (idx, id, what) in [
        (&d, 301, "Promo field in a card form"),
        (&imp, 120, "formless chat composer"),
        (&reg, 4, "register email"),
    ] {
        // A multi-letter key name that is not Enter is an unknown key: the row's click
        // class (D-403 (1)), not the form's implicit submission.
        let r = row(idx, 0, id);
        let click = class_of(&format!("c#{id}"), idx);
        let enter = key_class(r, "Enter", idx);
        assert!(click < enter, "{what}: click {click:?} vs Enter {enter:?}");
        for k in NOT_ENTER {
            assert_eq!(key_class(r, k, idx), click, "{what} k#{id}={k:?}");
        }
    }
    assert_eq!(class_of("k#301=Enterprise", &d), Class::Navigate);
    assert_eq!(class_of("k#301=Enter", &d), Class::Pay);
}

// ---- item 22: raise-only (hard rule 4) and the chord guard over every fixture ----

fn class_by_name(s: &str) -> Class {
    *Class::ALL
        .iter()
        .find(|c| format!("{c:?}") == s)
        .unwrap_or_else(|| panic!("unknown class {s:?}"))
}

/// Every (fixture, row, probe) of `common::ALL` x `common::raise_programs`, keyed as in
/// the baseline file.
fn current_classes() -> BTreeMap<(String, String, String), Class> {
    let mut out = BTreeMap::new();
    for (name, json) in ALL {
        let idx = rows(json);
        for r in &idx {
            for (label, program) in raise_programs(r) {
                let key = (name.to_string(), ref_of(r), label);
                let class = class_of(&program, &idx);
                assert!(out.insert(key.clone(), class).is_none(), "dup {key:?}");
            }
        }
    }
    out
}

#[test]
fn raise_only_every_fixture_vs_pre_d408() {
    let now = current_classes();
    if let Ok(path) = std::env::var("T19_WRITE_BASELINE") {
        let mut text = String::from(
            "# T-19 item 22: class per (fixture, row, probe) with crates/sb-act/src at 3122050\n",
        );
        for ((f, r, l), c) in &now {
            text.push_str(&format!("{f}\t{r}\t{l}\t{c:?}\n"));
        }
        std::fs::write(&path, text).expect("write baseline");
        eprintln!("wrote {} entries to {path}", now.len());
        return;
    }
    let mut base = BTreeMap::new();
    for line in BASELINE
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
    {
        let p: Vec<&str> = line.split('\t').collect();
        assert_eq!(p.len(), 4, "bad baseline line {line:?}");
        base.insert(
            (p[0].to_string(), p[1].to_string(), p[2].to_string()),
            class_by_name(p[3]),
        );
    }
    assert_eq!(
        base.keys().collect::<Vec<_>>(),
        now.keys().collect::<Vec<_>>(),
        "baseline and probes differ; regenerate the baseline"
    );
    let mut raised = 0;
    let mut lowered = Vec::new();
    for (k, &b) in &base {
        let c = now[k];
        if c < b {
            lowered.push(format!("{k:?}: {b:?} -> {c:?}"));
        } else if c > b {
            raised += 1;
            eprintln!("raised {k:?}: {b:?} -> {c:?}");
        }
    }
    eprintln!(
        "{} probes, {raised} raised, {} lowered",
        base.len(),
        lowered.len()
    );
    assert!(base.len() > 3000, "only {} probes", base.len());
    assert!(lowered.is_empty(), "lowered:\n{}", lowered.join("\n"));
}

#[test]
fn lowering_guard_enter_chords_every_fixture() {
    let mut checked = 0;
    for (name, json) in ALL {
        let idx = rows(json);
        for r in &idx {
            let rf = ref_of(r);
            let enter = key_class(r, "Enter", &idx);
            if r.flags.challenge {
                assert_eq!(enter, Class::Challenge, "{name} {rf}");
            }
            for k in ENTER_CHORDS {
                assert_eq!(key_class(r, k, &idx), enter, "{name} k{rf}={k:?}");
                checked += 1;
            }
        }
    }
    assert!(checked > 2000, "only {checked} checks");
}

// ---- item 23: D-408 (3) delete words ----

#[test]
fn d408_leave_group_and_wipe_device_are_delete() {
    let idx = rows(D408);
    for (r, what) in [
        (370, "Leave group"),
        (371, "Leave this group"),
        (372, "Wipe device"),
        (373, "Wipe this device"),
        (374, "Leave group (submit)"),
        (375, "Confirm under a Leave group? heading"),
    ] {
        assert_eq!(class_of(&format!("c#{r}"), &idx), Class::Delete, "{what}");
        assert_eq!(
            key_class(row(&idx, 0, r), "Enter", &idx),
            Class::Delete,
            "{what} Enter"
        );
    }
    for (r, what) in [
        (376, "Leave feedback"),
        (377, "Leave a comment"),
        (378, "Group settings"),
        (379, "Device settings"),
    ] {
        assert_eq!(class_of(&format!("c#{r}"), &idx), Class::Navigate, "{what}");
    }
}
